import{_ as t,c as o,o as r,ah as n}from"./chunks/framework.PvdZnrZd.js";const b=JSON.parse('{"title":"Subscription App Connector","description":"Subscription App Connector","frontmatter":{"title":"Subscription App Connector","description":"Subscription App Connector","date":"2025-08-04T00:00:00.000Z","author":"Chirag Tyagi"},"headers":[],"relativePath":"zenith/featured-app/connector/subscription-app-connector.md","filePath":"zenith/featured-app/connector/subscription-app-connector.md"}'),a={name:"zenith/featured-app/connector/subscription-app-connector.md"};function i(s,e,c,p,l,u){return r(),o("div",null,[...e[0]||(e[0]=[n('<p>Subscription App Connector: We have introduced an additional feature app in our <a href="https://store.webkul.com/Shopify-Multi-Vendor-Marketplace.html" target="_blank" rel="noreferrer">multivendor marketplace app</a> through which your seller can also allow their products on subscription.</p><p>Allow your sellers to create their own Subscription on a weekly, monthly basis.</p><h2 id="multivendor-marketplace-product-subscription-features" tabindex="-1"><strong>Multivendor Marketplace: Product Subscription Features</strong> <a class="header-anchor" href="#multivendor-marketplace-product-subscription-features" aria-label="Permalink to &quot;**Multivendor Marketplace: Product Subscription Features**&quot;">​</a></h2><p>Sellers can add subscription plans to their products and have the authority to create and manage these plans independently.</p><p>Admins can also create <a href="https://webkul.com/blog/webkul-product-subscription-app-for-shopify/" target="_blank" rel="noreferrer">product subscription</a> plans, either for all sellers or for specific sellers. Sellers can then choose and apply these plans to their products.</p><p>Enhance your product&#39;s sales growth by introducing a subscription model and incorporating special offers to boost customer engagement and retention.</p><p>Customers have the option to manually renew their subscriptions at their convenience.</p><h2 id="activation" tabindex="-1">Activation <a class="header-anchor" href="#activation" aria-label="Permalink to &quot;Activation&quot;">​</a></h2><p>To enable the Subscription App Connector, go to the Multivendor Marketplace Admin Panel,</p><p>hover over the three dots (...), select &#39;Feature App, &#39; search for &#39;Subscription App Connector, &#39; and enable it.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/image1776072596147.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/image1776072596147.webp" alt="image"></a></p><p>After clicking on the enable button, just click on agree to proceed.</p><p><strong>Note:</strong> You can enable the Subscription App Connector only after installing the Webkul Subscription App from the Shopify App Store on your Shopify store.</p><h2 id="admin-end" tabindex="-1">Admin End <a class="header-anchor" href="#admin-end" aria-label="Permalink to &quot;Admin End&quot;">​</a></h2><p>To enable this configuration, navigate to the Multivendor Marketplace Admin Panel &gt; Configuration &gt; Subscription Config</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/image1776072677980.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/image1776072677980.webp" alt="image"></a></p><p><strong>Allow Sellers To Add Subscription Plan:</strong></p><p>Once you enable this configuration, your sellers can create their own subscription plans and assign them to their products.<br><strong>Allow Admin to Create Subscription Plan for All Vendors:</strong></p><p>Once you enable this configuration, you (the Admin) can create subscription plans for all vendors and customize plans for specific vendors.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/image1776072719151.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/image1776072719151.webp" alt="mage"></a></p><p>To add, edit, or delete a product subscription plan for your vendors, go to the Multivendor Marketplace Admin Panel &gt; Products &gt; Product Subscription Plan.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/image1776072790754.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/image1776072790754.webp" alt="image"></a></p><h2 id="add-product-subscription-plan" tabindex="-1"><strong>Add Product Subscription Plan</strong> <a class="header-anchor" href="#add-product-subscription-plan" aria-label="Permalink to &quot;**Add Product Subscription Plan**&quot;">​</a></h2><p>To add a product subscription plan for your vendors, click on the &#39;Add Plan&#39; button and complete the form by providing the following details:</p><ol><li><strong>Plan Name:</strong> Enter your product subscription plan name.</li><li><strong>Assign to Vendor:</strong> You can assign your subscription plan to all vendors or to specific vendors. Once assigned, the selected vendors will be able to apply the subscription plan to their products.</li></ol><p>Note: To create a product subscription plan for your vendors, make sure you enable the configuration ‘Allow Admin to Create Subscription Plan for All Vendors’.</p><ol start="3"><li><strong>Discount on Subscription:</strong> If you wish to offer a discount on the product subscription, you can choose either a fixed price discount or a percentage discount. Alternatively, you can select &#39;No Discount. &#39;</li><li><strong>Delivery Type:</strong> You can offer delivery options based on either instant delivery or scheduled delivery.</li></ol><ul><li><strong>Instant Delivery:</strong> Determine the product delivery cycle based on the day the customer creates their subscription.</li><li><strong>Specific Delivery:</strong> Deliver the product on a specific day of the week or month, depending on the selected date or day.</li></ul><ol start="5"><li><strong>Subscription Type:</strong> The app offers subscription options based on either a weekly or monthly cycle.</li><li><strong>Minimum Delivery Count:</strong> You must fulfill orders for at least the minimum duration under a subscription before you can terminate it.</li></ol><p><strong>Note:</strong> <em>The minimum delivery count must be 2 or more.</em></p><ol start="7"><li><strong>Maximum Delivery Count:</strong> You can make deliveries up to the maximum limit under a subscription before it expires.</li><li>Click on Save Changes.</li></ol><h2 id="orders-on-subscribed-product" tabindex="-1">Orders: On subscribed product <a class="header-anchor" href="#orders-on-subscribed-product" aria-label="Permalink to &quot;Orders: On subscribed product&quot;">​</a></h2><p>Orders placed by customers through subscriptions will appear in the ‘Subscription Contract List’ under the Products Configuration dropdown menu.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/image1776072861876.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/image1776072861876.webp" alt="Product Subscription feature -view-order"></a></p><h2 id="seller-end" tabindex="-1">Seller End <a class="header-anchor" href="#seller-end" aria-label="Permalink to &quot;Seller End&quot;">​</a></h2><h2 id="product-subscription-plan" tabindex="-1">Product Subscription Plan <a class="header-anchor" href="#product-subscription-plan" aria-label="Permalink to &quot;Product Subscription Plan&quot;">​</a></h2><p>Sellers can view the subscription plans created by the Admin under the &#39;Product Subscription Plan&#39; option in the Product Configuration dropdown.</p><p>They can also add their own subscription plans if the Admin has enabled the &#39;Allow Sellers to Add Subscription Plan&#39; setting.</p><p>Sellers can add their subscription plans by navigating to the Multivendor Marketplace Seller Panel &gt; Products &gt; Product Subscription Plan and then clicking on &#39;Add Plan&#39;.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/image1776072910686.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/image1776072910686.webp" alt="Product Subscription feature -view-order"></a></p><h2 id="add-product-to-subscription" tabindex="-1">Add product to Subscription <a class="header-anchor" href="#add-product-to-subscription" aria-label="Permalink to &quot;Add product to Subscription&quot;">​</a></h2><p>If a seller wants to add a subscription to their product, they can go to their Seller Panel &gt; Products &gt; Product Listing.</p><p>From there, click on the three dots next to the product they want to update, then select &#39;Edit. &#39;</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/image1776072944486.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/image1776072944486.webp" alt="Product Subscription feature-add-subs"></a></p><p>In the Variant section, click on the three dots of the specific variant to which the subscription should be added, then click &#39;Edit&#39; again.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/image1776073287236.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/image1776073287236.webp" alt="Product Subscription feature -edit"></a></p><p>Finally, go to the &#39;Product Subscription&#39; section and select the desired subscription plan.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/image1776073380478.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/image1776073380478.webp" alt="Product Subscription feature -add"></a></p><h2 id="orders-on-subscribed-product-1" tabindex="-1">Orders: On subscribed product <a class="header-anchor" href="#orders-on-subscribed-product-1" aria-label="Permalink to &quot;Orders: On subscribed product&quot;">​</a></h2><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/image1776073464741.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/image1776073464741.webp" alt="Product Subscription feature -view-order-listing"></a></p><p>When a customer purchases a product with a subscription, the order will appear in the seller panel’s order listing.</p><p>The seller can click on &#39;View Contract&#39; to access the subscription details and view the order history for the subscribed product.&quot;.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/image1776074093317.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/image1776074093317.webp" alt="Product Subscription feature -view-orderview-contract"></a></p><p>When the seller checks an order from the &#39;Subscription Contract List&#39;, they can view details such as</p><p>the Subscription ID, Contract ID, Subscription Plan, Upcoming Bill Date, and the current Status of the plan.</p><p>By clicking on the three dots under the &#39;Action&#39; column, the seller can also access the contact details and order history.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/image1776074201979.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/image1776074201979.webp" alt="Product Subscription feature -view-order-contract-list"></a></p><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><p>When a customer visits the product description page to make a purchase, they will see both options: One-time Purchase and Purchase with Subscription.</p><p>Any discount available with the subscription will also be displayed on the product page.</p><p>Additionally, the minimum delivery count and the subscription frequency (whether it is weekly or monthly) will be shown as well.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/04/subscription-demo-product-1-1200x872.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/04/subscription-demo-product-1-1200x872.webp" alt="Product Subscription feature -view-order-demo-product"></a></p><p>From their account page, customers can view all their active subscription products, along with details such as the subscription plan name, next billing date, and current status.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/04/subscription-account-page-1200x641.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/04/subscription-account-page-1200x641.webp" alt="Product Subscription feature -view-order-account-page"></a></p><p>If they want to see more details about a specific subscription, they can click on &#39;View&#39; to access the full information.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/04/subscription-view-order-1200x626.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/04/subscription-view-order-1200x626.webp" alt="Product Subscription feature -view-order"></a></p>',66)])])}const h=t(a,[["render",i]]);export{b as __pageData,h as default};
